# -*- coding: utf-8 -*-
from author_common import *

def mc(doc,page,prompt,a,b,c,e,why,level='understand'):
    add(doc,page,'single_choice',prompt,'a',why,[a,b,c,e])
    q=qs[-1];q['id']=f'{doc}-x{sum(x["topic"]==doc for x in qs):02}';q['author_id']='question-engineer-b';q['cognitive_level']=level

d='p2-t3-d11'
mc(d,9,'Một host kết nối hai MCP server độc lập. Thành phần nào duy trì từng kết nối với server?','Một MCP client tương ứng mỗi server','Một server duy nhất phải đóng vai client cho mọi server khác','Mọi tool tự tạo host riêng thay client','Một resource URI thay thế toàn bộ kết nối client','Host quản lý các client; mỗi client duy trì kết nối chuyên biệt đến server tương ứng.')
mc(d,11,'Hai tool có schema hợp lệ nhưng agent thường chọn sai công cụ. Thông tin nào nên cải thiện trước?','Tên và mô tả công cụ thể hiện rõ khi nào dùng','Chỉ đổi thứ tự trường JSON theo alphabet','Chỉ rút ngắn tool name thành các ký tự không có nghĩa','Chỉ chuyển mọi tham số thành chuỗi tùy ý','Agent dựa tên và description để chọn tool; schema đúng kiểu chưa bảo đảm đúng ý định sử dụng.','apply')
mc(d,13,'MCP tool gặp lỗi có thể khắc phục bằng tham số khác. Kết quả lỗi nên hỗ trợ agent thế nào?','Trả lỗi có cấu trúc đủ để quyết định retry hoặc fallback','Trả chuỗi rỗng như thể đã thành công','Trả cùng payload thành công nhưng không đánh dấu lỗi','Giữ request treo vô hạn thay vì báo trạng thái','Structured errors cho phép phía gọi hiểu lỗi và chọn hành động phục hồi thích hợp.')
mc(d,14,'Muốn kiểm tool schema và error response trước khi thêm LLM vào hệ thống, nên dùng gì?','MCP Inspector gọi và kiểm server trực tiếp','Chỉ đọc câu trả lời tự nhiên của chatbot cuối cùng','Chỉ thử prompt mới cho đến khi agent chọn đúng','Chỉ kiểm UI host mà không gọi server','Inspector tách việc kiểm server khỏi hành vi LLM, giúp khoanh vùng schema, output và lỗi.')
mc(d,17,'Tool đổi định dạng output khiến consumer cũ không đọc được. Semantic version nên phản ánh thay đổi này thế nào?','Tăng major version vì phá tương thích','Chỉ tăng patch vì tool name chưa đổi','Giữ version vì schema đầu vào giống cũ','Chỉ sửa description và coi consumer tự thích nghi','Breaking change thuộc major version; contract output cũng là phần tương thích của tool.','apply')
mc(d,17,'Khi thay thế một MCP tool đang có consumer dùng, kế hoạch deprecation nào giúp migration?','Thông báo tool cũ và dành giai đoạn chuyển sang tool mới','Xóa tool cũ ngay khi thêm tool mới mà không thông báo','Giữ tên cũ nhưng âm thầm đổi mọi semantics','Đổi tool name mỗi lần gọi để tránh consumer cache','Deprecation cần cảnh báo và thời gian chuyển đổi thay vì đột ngột phá contract đang dùng.')
mc(d,19,'Workflow phân tích doanh thu rồi mở GitHub issue cần phối hợp dữ liệu và hành động ra sao?','Dùng kết quả truy vấn database làm đầu vào cho bước tạo issue','Tạo issue trước rồi xem issue như nguồn số liệu doanh thu','Buộc GitHub issue tool tự thay thế database query','Gộp mọi server thành một tool không phân biệt đọc và ghi','Host có thể phối hợp nhiều server: lấy dữ liệu, phân tích rồi gọi hành động phù hợp.','apply')
mc(d,22,'Schema database thay đổi theo môi trường. Vì sao cung cấp schema như dynamic context hữu ích cho truy vấn?','Agent biết cấu trúc bảng và cột thực tế trước khi viết query','Agent có thể bỏ kiểm tra tên cột vì mọi môi trường giống nhau','Schema context tự cấp quyền ghi cho mọi bảng','Schema context biến mọi câu hỏi thành truy vấn hợp lệ mà không cần kiểm','Dynamic schema context giảm việc suy đoán cấu trúc dữ liệu và giúp query dựa cấu trúc hiện hành.')
mc(d,25,'Một client muốn dùng tính năng không được server hỗ trợ. Bước giao thức nào giúp phát hiện giới hạn trước khi dùng?','Thương lượng capabilities giữa hai phía','Đoán hỗ trợ từ tên công cụ bất kỳ','Gọi mọi tính năng và coi timeout là kết quả rỗng','Chỉ dựa vào version của model thay server','Capability negotiation xác định các khả năng hai phía thực sự hỗ trợ.')
mc(d,28,'Agent cần tìm stack trace và release liên quan một lỗi production trước khi sửa code. Server chuyên biệt nào phù hợp?','Sentry MCP cho error context rồi GitHub MCP cho code liên quan','Playwright MCP thay thế hoàn toàn error event và release metadata','Docs MCP chỉ tìm API reference thay mọi runtime evidence','GitHub issue title duy nhất đủ thay stack trace thực tế','Sentry cung cấp lỗi, stack và release; kết hợp repository context để điều tra và sửa lỗi.','apply')
mc(d,28,'Agent nâng cấp thư viện cần kiểm API đúng phiên bản thay vì đoán theo kiến thức cũ. Nguồn MCP nào sát nhu cầu?','Context7 hoặc docs theo phiên bản thư viện','Sentry error count mà không có API reference','GitHub issue mới nhất bất kể phiên bản đang dùng','Playwright screenshot thay tài liệu API','Context7/docs cung cấp reference theo phiên bản, giảm nhầm API giữa các release.','apply')
mc(d,29,'Một MCP service được nhiều nhóm dùng chung và cần quản lý authentication tập trung nên chọn transport theo hướng nào?','HTTP endpoint dùng chung cho remote service','stdio bắt mọi người dùng chung một process cục bộ','Gắn service vào một terminal cá nhân rồi dùng như registry chung','Chỉ lưu tool descriptions trong file thay endpoint','HTTP phù hợp shared service có endpoint và quản lý auth; stdio thường gắn local process.')
mc(d,31,'Cấu hình MCP cần được chia sẻ cùng repository cho nhóm phát triển. Scope nào phù hợp?','Project scope qua .mcp.json','User scope toàn bộ các repository của một người','Local thử nghiệm riêng trên một máy không chia sẻ','Chỉ cấu hình trong một cuộc hội thoại tạm thời','Project scope đưa cấu hình theo repository; user scope phục vụ mặc định cá nhân xuyên nhiều repo.')
mc(d,31,'Một MCP tool có thể trả payload rất lớn nhưng agent ban đầu chỉ cần kết quả tổng quát. Thiết kế output nào tiết kiệm context?','Trả summary và ID/URI để fetch chi tiết khi cần','Luôn dump toàn raw payload vào mọi tool response','Bỏ mọi ID để agent không thể lấy chi tiết tiếp','Cắt payload ngẫu nhiên giữa trường dữ liệu mà không báo','Summary cộng tham chiếu giữ context gọn mà vẫn cho phép truy cập bằng chứng chi tiết.')
mc(d,32,'Search tool tìm được một tài liệu liên quan nhưng chỉ trả snippet. Vì sao cần thêm fetch tool?','Để đọc nội dung đầy đủ của kết quả đã xác định','Để lặp cùng search query mà không truy cập tài liệu','Để thay mọi kiểm chứng bằng ranking score','Để ghi đè tài liệu theo snippet đã thấy','Search giúp tìm ứng viên; fetch cung cấp nội dung gốc cần dùng cho công việc tiếp theo.')
mc(d,34,'Một MCP server chỉ cung cấp thao tác đọc. Vì sao vẫn phải kiểm phạm vi dữ liệu được phép truy cập?','Đọc dữ liệu nhạy cảm vẫn có thể dẫn tới exfiltration','Read-only tự động làm mọi dữ liệu trở thành công khai','Không ghi database thì không thể làm lộ thông tin','Quyền đọc luôn tương đương quyền chia sẻ ra mọi hệ thống','Read-only hạn chế sửa dữ liệu nhưng không ngăn rò rỉ dữ liệu từ kết quả đọc.')
mc(d,34,'Dùng cùng credentials cho MCP sandbox và production gây vấn đề gì?','Thao tác thử nghiệm có thể chạm dữ liệu hoặc quyền production','Server sandbox tự giới hạn quyền dù credentials có quyền production','Chỉ làm thay đổi tool descriptions, không ảnh hưởng quyền thực thi','Mọi write sandbox được tự động rollback trên production','Tách credentials và môi trường là ranh giới vận hành, tránh thử nghiệm mang quyền production.')

d='p2-t3-d12'
mc(d,7,'Một agent tự báo confidence 0.99. Vì sao chưa thể coi đó là xác suất quyết định đúng trong nghiệp vụ?','Confidence tự báo có thể chưa được calibration với độ chính xác thực tế','Confidence càng nhiều chữ số thì luôn càng chính xác','Confidence 0.99 loại bỏ nhu cầu kiểm business context','Mọi model đều dùng cùng thang xác suất đã được kiểm định cho mọi domain','Overconfidence và thiếu business context làm raw confidence khác độ đúng được kiểm chứng.')
mc(d,11,'Bước nào có thể chạy tự động trước một approval gate mà chưa tạo tác động gửi ra bên ngoài?','Soạn bản nháp email','Gửi email đã soạn cho khách hàng','Xóa record khách hàng theo nội dung email','Hủy tài khoản được nhắc đến trong email','Draft là bước chuẩn bị dễ sửa; gửi, xóa hay hủy tài khoản tạo tác động cần kiểm soát.','apply')
mc(d,17,'Human-on-the-Loop khác blocking approval ở thời điểm con người tham gia ra sao?','Agent thực thi trong khi người giám sát có thể can thiệp','Agent phải chờ approve trước từng hành động','Người duyệt phải tự thực thi mọi bước thay agent','Con người chỉ được sửa prompt trước khi hệ thống khởi chạy','HOTL là giám sát có khả năng can thiệp; HITL blocking dừng hành động trước khi được duyệt.')
mc(d,20,'Yêu cầu “báo cáo doanh thu Q1” thiếu khối Retail hay Corporate. Pattern nào giảm nguy cơ chạy query nặng trên sai tập dữ liệu?','Clarification trước thực thi','Approval cho một query đã tự đoán khối','Review kết quả sau khi đã phát hành báo cáo sai','Escalation mọi request doanh thu dù chỉ thiếu một trường','Clarification hỏi phần input thiếu trước khi chọn và thực thi truy vấn.','apply')
mc(d,21,'Agent gặp yêu cầu vượt phạm vi chuyên môn được phép xử lý. Pattern nào chuyển quyền giải quyết cho người phù hợp?','Escalation/handoff cho chuyên gia','Chỉ yêu cầu approve câu trả lời mà agent chưa đủ cơ sở','Tự tăng confidence để tiếp tục cùng luồng','Chỉ sửa định dạng draft mà giữ nguyên quyết định ngoài phạm vi','Escalation chuyển quyền kiểm soát khi case khó hoặc ngoài domain/phạm vi cho phép.')
mc(d,24,'Policy ứng dụng quy định một loại thao tác luôn phải duyệt. Agent báo confidence rất cao thì router nên làm gì?','Vẫn đưa qua gate theo hard rule','Cho model tự quyết có bypass gate hay không','Chỉ duyệt khi confidence thấp hơn ngưỡng chung','Tăng confidence threshold là đủ thay hard rule','Hard rules ở application layer có quyền ưu tiên hơn confidence do model tự đánh giá.','apply')
mc(d,28,'Một hệ thống dựa vào logprobs để định lượng uncertainty gặp giới hạn nào?','Xác suất token khó ánh xạ trực tiếp sang mức đúng nghiệp vụ','Logprobs luôn giải thích đầy đủ nguyên nhân quyết định nghiệp vụ','Token probability cao chứng minh action đúng chính sách','Mọi API đều cung cấp logprobs đầy đủ và giống nhau','Logprobs đo ở mức token; business correctness cần kiểm chứng và một số API không cung cấp đầy đủ.')
mc(d,31,'Năm lần suy luận độc lập cho cùng input đưa ra nhiều hành động khác nhau. Tín hiệu này gợi ý gì cho routing?','Độ nhất quán thấp nên cần thêm kiểm tra hoặc người hỗ trợ','Chỉ cần lấy lần đầu vì disagreement chứng minh lần đầu đúng','Tăng raw confidence của mọi phương án để tránh interrupt','Chọn phương án có chuỗi text dài nhất thay vì đánh giá bất định','Self-consistency dùng mức đồng thuận giữa các reasoning paths để phát hiện uncertainty.')
mc(d,35,'Cùng ngưỡng confidence 0.85 có nên mặc định dùng cho phân loại email nội bộ và quyết định ảnh hưởng khách VIP?','Không; cần tune theo dữ liệu và mức chấp nhận rủi ro','Có; một ngưỡng luôn giữ cùng cost of error giữa các domain','Có; confidence score tự mã hóa đầy đủ tác động kinh doanh','Không; chỉ cần dùng model lớn hơn thì bỏ hoàn toàn ngưỡng','Threshold phụ thuộc lịch sử hiệu năng và risk appetite của từng ứng dụng.')
mc(d,36,'Shadow mode giúp thu dữ liệu calibration theo cách nào?','Chạy song song và ghi đề xuất mà chưa tạo tác động thật','Tự thực thi mọi action rồi chỉ log các action thất bại','Chỉ đo raw confidence mà không đối chiếu người chấm','Ẩn mọi output để không thể so với quyết định con người','Shadow mode cho phép so proposal và confidence với độ đúng do người xác minh trước rollout.')
mc(d,39,'Một pending approval phải tồn tại qua restart server. Vì sao chỉ dùng MemorySaver chưa đủ?','State trong memory bị mất khi process khởi động lại','MemorySaver chỉ lưu final answer mà không lưu state','Thread ID tự khôi phục toàn bộ state dù không có storage','Approval UI luôn giữ bản snapshot đầy đủ thay backend','In-memory saver hợp dev/test; state cần tồn tại qua restart đòi persistent checkpointer.')
mc(d,40,'Hai khách hàng có pending approvals cùng lúc cần khác thread ID để đạt mục đích gì?','Tách state và luồng phê duyệt của từng trường hợp','Tăng raw confidence của mỗi quyết định','Dùng một approval để tự duyệt mọi case còn lại','Thay thế việc lưu state bằng tên hiển thị khách hàng','Thread ID định danh luồng để inspect/resume đúng state mà không lẫn case.')
mc(d,41,'Agent đã tạo báo cáo nháp an toàn nhưng chưa được phép gửi. Nên đặt điểm dừng ở đâu?','Sau node tạo nháp và trước bước phát hành','Sau khi gửi xong để người duyệt xác nhận tác động','Trước mọi truy vấn dữ liệu dù chỉ cần review bản nháp','Chỉ ở cuối toàn bộ graph sau mọi side effect','interrupt_after cho draft cho phép review kết quả trước bước phân phối có rủi ro.','apply')
mc(d,50,'Một action có TTL 15 phút được duyệt sau 2 giờ. Backend nên xử lý thế nào?','Đánh expired và yêu cầu chạy lại thay resume proposal cũ','Resume vì nút Approve luôn vô hiệu hóa TTL','Chỉ thay timestamp_generated bằng thời điểm approve','Giữ nguyên action và tăng confidence để bù độ cũ','TTL ngăn quyết định dựa context lỗi thời; kiểm tuổi action khi resume.','apply')
mc(d,56,'Giao diện duyệt thay đổi nhiều trường dữ liệu nên hiển thị diff để hỗ trợ điều gì?','Cho người duyệt thấy giá trị trước/sau và hệ quả thay đổi','Thay thế toàn bộ bằng một confidence score tổng','Chỉ hiển thị tên agent mà không có target record','Giấu trường đổi để người duyệt không bị phân tâm','Diff làm rõ delta cần quyết định, giảm approve theo thói quen thiếu hiểu biết.')
mc(d,62,'Một batch approval gồm nhiều giao dịch nhỏ và một giao dịch bất thường rất lớn. Thiết kế nào phù hợp?','Tách hoặc làm nổi bật outlier thay trộn vào phê duyệt hàng loạt','Đặt outlier giữa các dòng giống nhau và approve cả batch','Bỏ số tiền khỏi UI để mọi hàng có cùng độ dài','Dùng confidence trung bình batch thay risk từng action','Batching giảm tải nhưng không được che high-risk action giữa các case rủi ro thấp.','apply')
mc(d,69,'Approval rate rất cao có đủ chứng minh agent tốt không?','Không; có thể phản ánh rubber-stamping nên cần xem thêm override và response time','Có; approve là ground truth độc lập dù người duyệt không đọc','Có; nên bỏ audit ngay khi tỷ lệ approve vượt một ngưỡng','Không; approval rate cao luôn chứng minh agent kém','Cùng một tỷ lệ cao có thể do chất lượng tốt hoặc duyệt máy móc; cần diễn giải cùng hành vi và metrics liên quan.')

d='p2-t3-d13'
mc(d,6,'Mỗi component chạy riêng đều đạt kiểm thử nhưng hệ agent end-to-end vẫn lỗi. Điểm nào nên kiểm trước?','Interface format, error propagation và timeout tại ranh giới components','Chỉ độ dài README của từng component','Chỉ tăng model size mà không xem contract','Chỉ chạy lại unit test đã pass mà không nối components','Integration bugs thường nằm ở seams: format mismatch, thiếu xử lý lỗi và timeout không đồng bộ.','analyze')
mc(d,9,'Một agent chỉ được kiểm happy path. Bộ kiểm thử chức năng còn thiếu phạm vi nào?','Edge cases trong các user scenarios','Chỉ thêm nhiều lần lặp cùng happy path','Chỉ đo token cost thay hành vi người dùng','Chỉ đọc schema mà không thực thi request','Functional readiness cần cả happy và edge cases, không chỉ một demo trơn tru.')
mc(d,9,'Một pipeline multi-agent có từng agent chạy đúng độc lập. Kiểm thử handoff cần xác nhận điều gì?','Chuyển giao giữa các loại agent thực sự hoạt động','Chỉ kiểm mỗi agent có tên khác nhau','Chỉ đo tổng số agent được khai báo','Chỉ xác nhận một agent gọi được LLM','Handoff là hành vi tích hợp cần được thử trực tiếp thay suy từ agent riêng lẻ.')
mc(d,9,'Một service xử lý tốt từng query nối tiếp nhưng dự kiến có nhiều người dùng đồng thời. Phép thử nào còn cần?','Stress test các query đồng thời','Chỉ tăng số câu hỏi chạy tuần tự','Chỉ so RAGAS trên một câu hỏi cố định','Chỉ kiểm semantic cache của một request lặp lại','Concurrency tạo áp lực tài nguyên và điều phối khác với thử tuần tự.','apply')
mc(d,9,'Đội công bố có fallback provider. Bằng chứng nào xác minh khả năng này tốt hơn cấu hình đơn thuần?','Thử provider chính hỏng và kiểm hệ chuyển sang provider dự phòng','Chỉ lưu tên provider dự phòng trong environment','Chỉ xem API key dự phòng có đúng độ dài','Chỉ chạy provider chính thành công nhiều lần','Reliability cần fallback được kiểm trong failure thật hoặc mô phỏng, không chỉ khai báo.')
mc(d,10,'Muốn điều tra đầy đủ một lần agent chạy sai, coverage traces cần đạt mức nào?','Có trace cho mỗi agent run','Chỉ trace các request được chọn để demo','Chỉ log tổng số request theo ngày','Chỉ lưu final answer mà không có run context','Observability checklist yêu cầu trace mọi run để điều tra hành vi hệ thống.')
mc(d,10,'Metrics latency và error rate tăng trong vận hành. Thành phần nào biến số đo thành tín hiệu cần phản ứng?','Alert rules trên metrics','ADRs mô tả quyết định kiến trúc cũ','Tool schema mô tả tham số input','Benchmark target không có actual measurements','Metrics và dashboard cần alert rules để phát hiện bất thường vận hành, như P95 và error rate vượt ngưỡng.')
mc(d,12,'Muốn lượng hóa semantic cache tiết kiệm chi phí bao nhiêu, thiết kế đo nào phù hợp?','So chi phí cùng workload có và không có cache','Chỉ đếm số entry cache mà không đo token cost','Chỉ dùng giá API danh nghĩa mà không chạy workload','Chỉ đo latency rồi coi phần giảm là token savings','Đối chứng with/without cache trên workload cho phép tính cost reduction và tránh suy từ cache size.')
mc(d,12,'End-to-end latency cao nhưng chưa rõ component nào gây ra. Nên đo gì tiếp?','Trace latency từng component trong flow','Chỉ lấy thêm trung bình end-to-end của cùng request','Chỉ tăng cache TTL bất kể đoạn nào chậm','Chỉ giảm output tokens dù chưa biết bottleneck','Component profiling xác định thời gian nằm ở retrieval, model hay bước khác để tối ưu đúng chỗ.','analyze')
mc(d,13,'Benchmark report ghi target nhưng Actual đều là TBD. Thiếu sót chính là gì?','Chưa có số đo thực chứng minh hệ thống đạt hay không đạt','Target càng nhiều thì tự thay thế actual measurements','TBD tương đương pass nếu demo chạy được','Chỉ cần bỏ cột Status để report hoàn chỉnh','Benchmark là bằng chứng bằng actual metrics, không chỉ danh sách mục tiêu mong muốn.')
mc(d,13,'Một hệ có faithfulness tốt nhưng P95 vượt target. Cách kết luận benchmark nào hợp lý?','Ghi riêng chất lượng đạt và latency chưa đạt','Gộp hai metric và tuyên bố mọi mặt đều pass','Bỏ metric latency vì quality score cao','Đổi actual P95 thành target để giữ report thống nhất','Mỗi metric đánh giá một yêu cầu khác; quality cao không chứng minh đáp ứng latency target.','analyze')
mc(d,15,'Consumer mới muốn tự tích hợp API mà không hỏi đội phát triển từng trường input/output. Tài liệu cần cung cấp gì?','OpenAPI/tool schemas cùng example requests và responses','Chỉ lịch sử quyết định chọn thuật toán','Chỉ checklist xử lý incident của on-call','Chỉ screenshot dashboard mà không contract','API specs mô tả interface và ví dụ cụ thể giúp consumer tự sử dụng.')
mc(d,17,'Feedback peer review nào có tính actionable cao nhất?','Nêu lỗi cụ thể, bằng chứng và thay đổi đề xuất','Chỉ viết “cần code tốt hơn” không chỉ vị trí','Chỉ chấm điểm tổng mà không giải thích','Chỉ ghi cảm nhận về tác giả thay hành vi hệ thống','Structured feedback cần cụ thể, có ví dụ và hướng cải thiện để người nhận có thể hành động.')
mc(d,17,'Sau khi chạy demo thành công, reviewer nên thử gì để đánh giá reliability?','Edge cases và error paths cùng fallback/error handling','Chỉ lặp lại đúng input demo mà không gây lỗi','Chỉ đếm số dependency được cài đặt','Chỉ đổi màu UI rồi kiểm screenshot','Peer review đi từ happy path sang edge/error paths để tìm thiếu sót mà demo bình thường không bộc lộ.')
mc(d,20,'Trước khi chạy E2E cho pipeline vừa ghép, bước nào giúp khoanh vùng lỗi tích hợp sớm?','Validate interface contracts giữa các components','Đổi toàn bộ component cùng lúc khi chưa đo lỗi','Chỉ xác nhận từng file code import được','Chỉ thử UI cuối cùng mà không kiểm data format','Contract validation giảm lỗi format mismatch tại seams trước khi chúng lan thành lỗi E2E khó truy vết.')
mc(d,21,'Chaos test tắt provider chính giữa một agent run nhằm kiểm điều gì khác với test khởi động bình thường?','Circuit breaker và fallback trong failure khi luồng đang chạy','Chỉ xác nhận model chính có thể trả lời khi khỏe','Chỉ đo chính tả trong final answer','Chỉ xác nhận README có nhắc provider dự phòng','Failure giữa run kiểm khả năng phục hồi của cơ chế bảo vệ và chuyển provider ngay trong vận hành.')
mc(d,23,'Peer review đã nêu ba lỗi ưu tiên cao. Bằng chứng nào thể hiện vòng phản hồi được khép lại?','Đưa các cải thiện ưu tiên vào code rồi kiểm lại','Chỉ lưu feedback trong thư mục mà không xử lý','Chỉ cảm ơn reviewer và giữ mọi lỗi như cũ','Chỉ tăng số dòng tài liệu mà không liên quan lỗi','Review có giá trị khi feedback dẫn đến cải thiện và được xác minh trong hệ thống.')
